#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-or-later
# gen_ko_mar.py -- KO trial: splice v13 dialogue KO bytes into the Saturn
# Maria fight scripts (mods/.../mod_maria_boss_data.h, generated by
# gen_cen_maria.py -- this runs after it, every build; fail-closed).
# Method: same greedy EN-match + order-based KO fill as gen_ko_splice.py,
# but the arrays are MOD_RO (rodata) so sizes may change; the KO variant
# goes under #ifdef MOD_KO, EN branch byte-identical (modulo one newline).
import io
from ko_paths import KO_WK, KO_REPO  # noqa: E402
import os
import re

REPO = KO_REPO
WK = KO_WK
HDR = (REPO + "/mods/sotn-ultimate/src/maria_saturn/mod_maria_boss_data.h")
BAK = HDR + ".ko_en"


def load_map():
    mp = {}
    for line in io.open(WK + "/P4시험/" + __import__("ko_font_profile").P["map_name"] + "", encoding="utf-8"):
        p = line.rstrip("\n").split("\t")
        if len(p) >= 2 and len(p[0]) == 1 and p[1].startswith("0x"):
            mp[p[0]] = int(p[1], 16)
    assert len(mp) >= 700, len(mp)  # glyph-map size sanity check
    return mp


def enc(s, mp):
    out = bytearray()
    for ch in s.replace("…", "..."):
        o = ord(ch)
        if o < 128:
            out.append(o)
        else:
            assert ch in mp, repr(ch)
            out.append(mp[ch] >> 8)
            out.append(mp[ch] & 0xFF)
    return bytes(out)


def load_rows(want):
    rows = {}
    for line in io.open(os.environ.get("KO_V14", (KO_WK + "/검수/번역_v14.tsv")), encoding="utf-8"):
        p = line.rstrip("\n").split("\t")
        if len(p) > 3 and p[0].startswith(want):
            rows[p[0]] = (p[2], p[3].replace("…", "...").replace("\\n", "/"))
    return rows


def c_decode(tok):
    body = tok[1:-1]
    if body.startswith("\\x") or body.startswith("\\u"):
        return chr(int(body[2:], 16))
    if body.startswith("\\"):
        return {"'": "'", "\\": "\\", "n": "\n", "0": "\0"}.get(body[1:], body)
    return body


def split_top(body):
    toks, depth, cur = [], 0, ""
    inch = False
    esc = False
    for ch in body:
        if inch:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == "'":
                inch = False
            continue
        if ch == "'":
            inch = True
            cur += ch
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            toks.append(cur)
            cur = ""
            continue
        cur += ch
    toks.append(cur)
    return [t.strip() for t in toks]


def is_text(tok):
    return len(tok) >= 3 and tok.startswith("'") and tok.endswith("'")


def convert(body, keys, tsv, mp, tag):
    toks = split_top(body)
    # NOTE: body separators are not uniform (inner macro commas, leading
    # newline+indent), so the EN branch below reuses the body verbatim.
    # slots of consecutive text-token indexes, split on LINE_BREAK-ish ops
    slots, cur = [], []
    for i, t in enumerate(toks):
        if is_text(t):
            cur.append(i)
        elif t.startswith("LINE_BREAK") or t.startswith("NEXT_DIALOG") or \
                t.startswith("CLOSE_DIALOG") or t.startswith("END_CUTSCENE"):
            if cur:
                slots.append(cur)
                cur = []
    if cur:
        slots.append(cur)
    texts = [c_decode(toks[i]) for grp in slots for i in grp]
    # EN segs per key in index order
    skeys = sorted(keys, key=lambda k: int(k.rsplit(":", 1)[1]))
    # EN source: legacy text, or "#n1/n2/.." slot counts per segment (public TSV)
    cnt_mode = [tsv[k][0].startswith("#") for k in skeys]
    assert all(cnt_mode) or not any(cnt_mode), (tag, "mixed EN counts/text")
    en_res = {}
    if all(cnt_mode):
        csi = 0
        for k in skeys:
            segs = []
            for c in tsv[k][0][1:].split("/"):
                n = int(c)
                segs.append("".join(c_decode(toks[i]) for slot in slots[csi:csi + n] for i in slot))
                csi += n
            en_res[k] = "/".join(segs)
    else:
        for k in skeys:
            en_res[k] = tsv[k][0].replace("\\n", "/")
    en_segs = []
    for k in skeys:
        for j, s in enumerate(en_res[k].split("/")):
            en_segs.append((k, j, s))
    si = 0
    seg_grp = {}
    for (k, j, s) in en_segs:
        acc = ""
        n = 0
        while si + n < len(slots) and len(acc) < len(s):
            for i in slots[si + n]:
                acc += c_decode(toks[i])
            n += 1
            if acc == s:
                break
        assert acc == s, (tag, k, j, repr(s), repr(acc))
        seg_grp[(k, j)] = slots[si:si + n]
        si += n
    assert si == len(slots), (tag, "leftover slots", len(slots) - si)
    _dump = os.environ.get("KO_DUMP_EN")
    if _dump and not all(cnt_mode):
        with io.open(_dump, "a", encoding="utf-8", newline="") as _f:
            for k in skeys:
                _f.write(k + "\t#" + "/".join(str(len(seg_grp[(k, j)])) for j in range(len(en_res[k].split("/")))) + "\n")
    repl = {}
    for k in skeys:
        es = en_res[k].split("/")
        ks = tsv[k][1].split("/")
        groups = []
        for j, s in enumerate(es):
            if s == "":
                continue
            assert len(seg_grp[(k, j)]) > 0, (tag, k, j)
            groups.append(seg_grp[(k, j)])
        knon = [x for x in ks if x != ""]
        assert len(knon) <= len(groups), (tag, k, len(knon), len(groups))
        for gi, grp in enumerate(groups):
            payload = enc(knon[gi], mp) if gi < len(knon) else b""
            flat = [i for slot in grp for i in slot]
            for n2, i in enumerate(flat):
                repl[i] = ["0x%02X" % b for b in payload] if n2 == 0 else []
    kos = []
    for i, t in enumerate(toks):
        if i in repl:
            kos.extend(repl[i])
        else:
            kos.append(t)
    return toks, kos


def main():
    mp = load_map()
    src = io.open(HDR, encoding="utf-8").read()
    if "g_MbScriptPre[] MOD_RO = {\n#ifdef MOD_KO" in src:
        assert os.path.exists(BAK), "KO-patched without backup: " + HDR
        src = io.open(BAK, encoding="utf-8").read()
    else:
        if not os.path.exists(BAK):
            io.open(BAK, "w", encoding="utf-8", newline="").write(src)
    for arr0 in ("g_MbScriptPre", "g_MbScriptPost"):
        assert re.search(r"u8 " + arr0 + r"\[\] MOD_RO = \{\n    \w", src), \
            "unexpected shape (gen_cen_maria.py output changed?): " + arr0
    for arr, want in (("g_MbScriptPre", "mod_maria_boss_data.h:g_MbScriptPre:"),
                      ("g_MbScriptPost", "mod_maria_boss_data.h:g_MbScriptPost:")):
        tsv = dict((k, v) for k, v in load_rows(want).items())
        assert len(tsv) == 7, (arr, len(tsv))
        m = re.search(r"u8 " + arr + r"\[\] MOD_RO = \{(.*?)\n\};",
                      src, re.S)
        assert m, arr
        body = m.group(1)
        en_toks, ko_toks = convert(body, list(tsv.keys()), tsv, mp, arr)
        en_block = body
        nke = sum(1 for t in en_toks if is_text(t))
        ko_lines = []
        line = []
        for t in ko_toks:
            line.append(t)
            if len(line) >= 12:
                ko_lines.append("    " + ", ".join(line) + ",")
                line = []
        if line:
            ko_lines.append("    " + ", ".join(line))
        ko_block = "\n" + "\n".join(ko_lines) + "\n"
        new = ("u8 " + arr + "[] MOD_RO = {\n#ifdef MOD_KO\n" + ko_block +
               "#else" + en_block + "\n#endif\n};")
        src = src[:m.start()] + new + src[m.end():]
        nke = sum(1 for t in en_toks if is_text(t))
        nke2 = sum(1 for t in ko_toks if t.startswith("0x"))
        print(arr, "EN text toks=", nke, "KO bytes=", nke2)
    io.open(HDR, "w", encoding="utf-8", newline="").write(src)
    print("OK wrote", HDR)


main()
